export const greeceGuides = greeceClusters.flatMap((cluster) => cluster.guides.map((guide) => ({ ...guide, cluster })));
export const greeceRoutes = ['/greece/', ...greeceClusters.map((cluster) => `/greece/${cluster.slug}/`), ...greeceGuides.map((guide) => `/greece/${guide.cluster.slug}/${guide.slug}/`)];

if (greeceClusters.length !== 8 || greeceGuides.length !== 24 || new Set(greeceRoutes).size !== 33) {
  throw new Error('Greece source must contain eight distinct hubs and twenty-four distinct guides.');
}
for (const cluster of greeceClusters) {
  if (cluster.guides.length !== 3 || new Set(cluster.guides.map((guide) => guide.slug)).size !== 3) throw new Error(`Invalid route set in ${cluster.slug}`);
  for (const guide of cluster.guides) {
    for (const key of ['summary', 'purpose', 'stay', 'access', 'mobility', 'duration', 'combine', 'bookings', 'season', 'fallback', 'tradeoff']) {
      if (!guide[key] || guide[key].length < 80) throw new Error(`${guide.slug}: editorial field ${key} is missing or too thin.`);
    }
  }
}
